update_rule.pseudocode:
for each media channel c that broadcasts today:
  for each person p:
    if Bernoulli(reach_c):
      if c.message_type == 'campaign':
        p.exposure_to_campaigns += 1
        delta_belief = campaign_intensity * campaign_credibility * (0.5 + 0.5*p.trust_in_authority)
        p.belief_pro_mask = clip(p.belief_pro_mask + delta_belief, 0, 1)
        p.perceived_risk = clip(p.perceived_risk + 0.5*campaign_intensity*campaign_credibility, 0, 1)
      else if c.message_type == 'misinformation':
        if Bernoulli(misinformation_rate):
          p.exposure_to_misinformation += 1
          delta_belief = - misinformation_credibility * (0.5 + 0.5*(1 - p.trust_in_authority))
          p.belief_pro_mask = clip(p.belief_pro_mask + delta_belief, 0, 1)
          p.trust_in_authority = clip(p.trust_in_authority - 0.1*misinformation_credibility, 0, 1)

for each person p:
  policy_pressure = 1.0 if PolicyMaker.current_policy == 'mandate' else 0.0
  utility = weight_belief*p.belief_pro_mask + weight_risk*p.perceived_risk + weight_norm*p.perceived_norm + weight_trust*p.trust_in_authority + weight_policy*policy_pressure
  cost = perceived_cost_per_mask
  U = utility - cost
  prob_wear = sigmoid(U / decision_temperature)
  p.mask_wearing_today = Bernoulli(prob_wear)
  if p.mask_wearing_today:
    if p.has_masks_inventory < mask_usage_per_day:
      need_qty = ceil(mask_usage_per_day - p.has_masks_inventory) + purchase_planning_horizon_days
      affordable_qty = floor((p.budget / mask_cost_base))
      buy_qty = max(0, min(need_qty, affordable_qty))
      if buy_qty > 0: emit purchase_intent(p.id, buy_qty)
    p.has_masks_inventory = max(0, p.has_masks_inventory - mask_usage_per_day)
  else:
    # compliance decay reduces future propensity when no mandate
    if PolicyMaker.current_policy == 'none':
      p.belief_pro_mask = clip(p.belief_pro_mask * (1 - compliance_decay_rate), 0, 1)

reset denied_entries_count=0; fines_count=0; clear enforcement_actions_log
for each person p:
  for each location L in todays_schedule(p):
    if L.mask_policy_required and not p.mask_wearing_today:
      check_prob = enforcement_check_probability_base * L.enforcement_strictness
      if Bernoulli(check_prob):
        if Bernoulli(denial_probability_if_caught):
          denied_entries_count += 1
          log(enforcement_actions_log, {p.id, L.id, 'denied'})
        else:
          if Bernoulli(prob_fine_given_noncompliance):
            fines_count += 1
            p.budget = max(0, p.budget - fine_amount)
            log(enforcement_actions_log, {p.id, L.id, 'fined'})
